  GameApplication game(c,"title");std::string error;need(game.restore(saved,error),"Native07 failure fixture restore rejected");const auto original=game.session().exportState();
  game.configureSaveDirectory(directory,[=](std::string_view point){if(point==stage){throw std::runtime_error("Injected07 publication failure");}});
  game.update(key());need(game.mode()==ApplicationMode::Saving,"Native07 legal monitor failure fixture absent");for(int n=0;n<200;++n){game.update({});}game.update(key());game.update(key());game.update(key(InputAction::Up));game.update(key());
