  if(std::string(stage)=="after-replace"){
   need(clean.list().at(0).state==SlotState::RecoveryRequired,"07 ambiguous publication not marked recovery");game.update(key(InputAction::Cancel));game.update(key());const auto choices=clean.recoveryChoices(1);int selected=-1;for(int i=0;i<int(choices.size());++i){if(choices[i].snapshot==saved){selected=i;}}
   need(selected>=0,"07 lost original complete backup");for(int n=0;n<selected;++n){game.update(key(InputAction::Down));}game.update(key());game.update(key(InputAction::Up));game.update(key());
   need(game.mode()==ApplicationMode::Saving,"Recovering old07 backup falsely completed current Save");
  }
  game.update(key(InputAction::Cancel));game.update(key(InputAction::Cancel));need(game.mode()==ApplicationMode::Playing&&game.session().saveCount()==original.saveCount&&game.session().variable(399)==GameSession(c.items,original,c.facts).variable(399)&&game.session().flag(1)&&game.session().flag(18),"07 failure/recovery changed live counters or controls");
